package com.bananalab.lite;
import java.util.*;import java.text.Normalizer;
/** Original deterministic formant voice. No external recordings/model or Android TTS. */
final class VoiceSynth{
 static final class Phone{char c;float start,length;Phone(char c,float s,float n){this.c=c;start=s;length=n;}}
 static final class Script{final List<Phone> phones=new ArrayList<>();float duration;}
 private static final LinkedHashMap<String,Script> scripts=new LinkedHashMap<>(16,.75f,true);
 static float speed(String voice){return voice.equals("aguda")?1.07f:voice.equals("grave")?.94f:1;}
 static synchronized Script script(String text,String voice){String key=voice+"|"+text;Script old=scripts.get(key);if(old!=null)return old;Script out=new Script();String q=text.toLowerCase(java.util.Locale.ROOT).replace("ñ","~");q=Normalizer.normalize(q,Normalizer.Form.NFD).replaceAll("\\p{M}","");q=q.replace("ch","C").replace("rr","R").replace("ll","Y").replaceAll("qu(?=[ei])","k").replaceAll("gu(?=[ei])","g").replaceAll("g(?=[ei])","x").replaceAll("c(?=[ei])","s").replace('c','k').replace('z','s').replace('j','x').replace('v','b').replace("h","").replace('~','N').replaceAll("y\\b","i").replace('y','Y').replace('w','u').replace('q','k');float t=.04f;
  for(int i=0;i<q.length();i++){char c=q.charAt(i);float n;if("aeiou".indexOf(c)>=0)n=.115f;else if("mnNlYrR".indexOf(c)>=0)n=.075f;else if("pbtdkg".indexOf(c)>=0)n=.07f;else if("fsxC".indexOf(c)>=0)n=.09f;else if(c==' ')n=.045f;else if(",;:".indexOf(c)>=0)n=.16f;else if(".!?".indexOf(c)>=0)n=.26f;else continue;n/=speed(voice);out.phones.add(new Phone(c,t,n));t+=n;}out.duration=t+.07f;scripts.put(key,out);while(scripts.size()>32)scripts.remove(scripts.keySet().iterator().next());return out;
 }
 static float duration(String text,String voice){return script(text,voice).duration;}
 static float mouth(String text,String voice,float second){Script s=script(text,voice);for(Phone p:s.phones)if(second>=p.start&&second<p.start+p.length){float e=(second-p.start)/p.length,fade=Math.min(1,Math.min(e*8,(1-e)*8));return ("aeiou".indexOf(p.c)>=0?1:"mnNlYrR".indexOf(p.c)>=0?.4f:"pbtdkgfsxC".indexOf(p.c)>=0?.18f:0)*fade;}return 0;}
 static short[] render(String text,String voice,int identity){Script script=script(text,voice);int n=(int)Math.ceil(script.duration*Soundtrack.RATE);float[] raw=new float[n];Random rng=new Random(0xBABA1234L+identity);double phase=0;float base=voice.equals("grave")?98:voice.equals("aguda")?195:voice.equals("robotica")?145:125+((identity%4+4)%4)*13;double[] y1=new double[3],y2=new double[3];float peak=.0001f;
  for(Phone p:script.phones){char c=p.c;boolean vowel="aeiou".indexOf(c)>=0,nasal="mnN".indexOf(c)>=0,liquid="lYrR".indexOf(c)>=0,fric="fsxC".indexOf(c)>=0,stop="pbtdkg".indexOf(c)>=0;if(!vowel&&!nasal&&!liquid&&!fric&&!stop)continue;double[] form=c=='a'?new double[]{720,1200,2500}:c=='e'?new double[]{450,1850,2600}:c=='i'||c=='Y'?new double[]{300,2250,3000}:c=='o'?new double[]{500,900,2400}:c=='u'?new double[]{330,700,2200}:nasal?new double[]{260,1100,2100}:new double[]{400,1500,2400};double[] rr=new double[3],aa=new double[3],gain=new double[3];for(int k=0;k<3;k++){double freq=fric?(c=='s'?3500:1800)+k*450:form[k],bw=fric?800:100+k*60;rr[k]=Math.exp(-Math.PI*bw/Soundtrack.RATE);aa[k]=2*rr[k]*Math.cos(2*Math.PI*freq/Soundtrack.RATE);gain[k]=1-rr[k];}int start=Math.round(p.start*Soundtrack.RATE),end=Math.min(n,Math.round((p.start+p.length)*Soundtrack.RATE));
   for(int i=start;i<end;i++){double t=i/(double)Soundtrack.RATE,u=(i-start)/(double)Math.max(1,end-start),envelope=Math.min(1,Math.min(u*12,(1-u)*12));double pitch=base*(voice.equals("robotica")?1:(1+.025*Math.sin(t*4)-.05*t/script.duration));phase+=pitch/Soundtrack.RATE;if(phase>=1)phase-=1;double noise=rng.nextDouble()*2-1,source=(2*phase-1)*.3;if(c=='R')source*=.35+.65*Math.abs(Math.sin(t*2*Math.PI*25));if(stop){source*=u<.55?.05:.2;if(u>.5&&u<.64)source+=noise*.55;}if(fric)source=noise*(c=='s'?.45:.3);double sum=0;
    for(int k=0;k<3;k++){double yy=gain[k]*source+aa[k]*y1[k]-rr[k]*rr[k]*y2[k];y2[k]=y1[k];y1[k]=yy;sum+=yy*(k==0?1:k==1?.7:.35);}if(nasal)sum*=.7;if(stop)sum*=.8;float v=(float)(sum*envelope);raw[i]+=v;peak=Math.max(peak,Math.abs(raw[i]));}
  }short[] pcm=new short[n];for(int i=0;i<n;i++)pcm[i]=(short)Math.max(-26000,Math.min(26000,raw[i]/peak*20000));return pcm;
 }
}
